   421→### 协程最佳实践
   422→
   423→```csharp
   424→// ✅ 正确：缓存 WaitForSeconds
   425→public class CooldownSystem : MonoBehaviour
   426→{
   427→    private static readonly WaitForSeconds WaitOneSecond = new WaitForSeconds(1f);
   428→    private static readonly WaitForSeconds WaitPointOne = new WaitForSeconds(0.1f);
   429→
   430→    private Coroutine _cooldownCoroutine;
   431→
   432→    public void StartCooldown(float duration)
   433→    {
   434→        if (_cooldownCoroutine != null)
   435→        {
   436→            StopCoroutine(_cooldownCoroutine);
   437→        }
   438→        _cooldownCoroutine = StartCoroutine(CooldownRoutine(duration));
   439→    }
   440→
   441→    private IEnumerator CooldownRoutine(float duration)
   442→    {
   443→        float elapsed = 0f;
   444→        while (elapsed < duration)
   445→        {
   446→            elapsed += Time.deltaTime;
   447→            yield return null;
   448→        }
   449→        OnCooldownComplete();
   450→    }
   451→}
   452→
   453→// ❌ 错误：每次创建新的 WaitForSeconds
   454→private IEnumerator BadCoroutine()
   455→{
   456→    yield return new WaitForSeconds(1f); // 每次分配新对象!
   457→}
