   540→## 对象池规范
   541→
   542→### 通用对象池实现
   543→
   544→```csharp
   545→public class ObjectPool<T> where T : Component
   546→{
   547→    private readonly Queue<T> _pool = new Queue<T>();
   548→    private readonly T _prefab;
   549→    private readonly Transform _parent;
   550→    private readonly int _initialSize;
   551→
   552→    public ObjectPool(T prefab, Transform parent, int initialSize = 10)
   553→    {
   554→        _prefab = prefab;
   555→        _parent = parent;
   556→        _initialSize = initialSize;
   557→
   558→        Preallocate();
   559→    }
   560→
   561→    private void Preallocate()
   562→    {
   563→        for (int i = 0; i < _initialSize; i++)
   564→        {
   565→            var obj = CreateNew();
   566→            obj.gameObject.SetActive(false);
   567→            _pool.Enqueue(obj);
   568→        }
   569→    }
   570→
   571→    public T Get()
   572→    {
   573→        T obj = _pool.Count > 0 ? _pool.Dequeue() : CreateNew();
   574→        obj.gameObject.SetActive(true);
   575→        return obj;
   576→    }
   577→
   578→    public void Return(T obj)
   579→    {
   580→        obj.gameObject.SetActive(false);
   581→        obj.transform.SetParent(_parent);
   582→        _pool.Enqueue(obj);
   583→    }
   584→
   585→    private T CreateNew()
   586→    {
   587→        return Object.Instantiate(_prefab, _parent);
   588→    }
   589→}
   590→```
